const LIMITE: i32 = 100;

fn main() {
    let nome: &str = "Ferris";
    let mut nivel: i32 = 1;
    nivel += 1;

    // if/else funcionando como expressão que retorna valor
    let status = if nivel >= 2 { "Pronto" } else { "Iniciante" };
    println!("{} ({}) -> {}", nome, LIMITE, status);
}

